<?php require_once "config/database.php";require_once "includes/functions.php";start_session();if(!isset($_SESSION["cart"]))$_SESSION["cart"]=[];if($_SERVER["REQUEST_METHOD"]==="POST"){$id=(int)$_POST["product_id"];$qty=max(1,(int)($_POST["quantity"]??1));if($_POST["action"]==="add")$_SESSION["cart"][$id]=($_SESSION["cart"][$id]??0)+$qty;if($_POST["action"]==="remove")unset($_SESSION["cart"][$id]);header("Location: cart.php");exit;}$items=[];$total=0;if($_SESSION["cart"]){$ids=array_keys($_SESSION["cart"]);$in=implode(",",array_fill(0,count($ids),"?"));$st=$pdo->prepare("SELECT * FROM products WHERE id IN($in)");$st->execute($ids);foreach($st as $p){$q=$_SESSION["cart"][$p["id"]];$sub=$q*$p["price"];$total+=$sub;$items[]=[$p,$q,$sub];}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cart | JKtech.lk</title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php include "includes/navbar.php";?><main class="container page"><span class="eyebrow">SHOPPING CART</span><h1>Your cart.</h1><?php foreach($items as [$p,$q,$sub]):?><div class="cart-row"><b><?=e($p["name"])?></b><span><?=$q?> × Rs. <?=number_format($p["price"],2)?></span><strong>Rs. <?=number_format($sub,2)?></strong><form method="post"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=$p["id"]?>"><button class="add">Remove</button></form></div><?php endforeach;?><div class="cart-total"><h2>Total: Rs. <?=number_format($total,2)?></h2><?php if($items):?><a class="btn primary" href="checkout.php">Checkout →</a><?php endif;?></div></main></body></html>